import"//resources/polymer/v3_0/iron-icon/iron-icon.js";import"//resources/polymer/v3_0/iron-media-query/iron-media-query.js";import"./components/common_styles/oobe_dialog_host_styles.css.js";import"./components/dialogs/oobe_adaptive_dialog.js";import"./components/oobe_icons.html.js";import"./components/common_styles/oobe_common_styles.css.js";import"./icons.html.js";import{ColorChangeUpdater}from"//resources/cr_components/color_change_listener/colors_css_updater.js";import{PolymerElement}from"//resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./curtain_screen.html.js";function setDialogSizeAndOrientation(){document.documentElement.style.setProperty("--oobe-oobe-dialog-height-base",window.innerHeight+"px");document.documentElement.style.setProperty("--oobe-oobe-dialog-width-base",window.innerWidth+"px");document.documentElement.setAttribute("orientation",window.innerWidth>window.innerHeight?"horizontal":"vertical")}class CurtainScreenElement extends PolymerElement{static get is(){return"curtain-screen"}static get template(){return getTemplate()}ready(){super.ready();this.$.mainCurtainDialog.onBeforeShow();setDialogSizeAndOrientation();const fontLink=document.createElement("link");fontLink.rel="stylesheet";fontLink.href="chrome://theme/typography.css";document.head.appendChild(fontLink);document.body.classList.add("jelly-enabled");if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",this.listenToColorChanges)}else{this.listenToColorChanges()}}listenToColorChanges(){const updater=ColorChangeUpdater.forDocument();updater.start();updater.refreshColorsCss()}connectedCallback(){super.connectedCallback();window.addEventListener("resize",setDialogSizeAndOrientation)}disconnectedCallback(){super.disconnectedCallback();window.removeEventListener("resize",setDialogSizeAndOrientation)}}customElements.define(CurtainScreenElement.is,CurtainScreenElement);